{"command":"cat > cli.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

const helpText = "Usage:\n" +
	"  pingu [OPTIONS] HOST\n\n" +
	"`ping` command but with pingu\n\n" +
	"Application Options:\n" +
	"  -c, --count=     Stop after <count> replies (default: 20)\n" +
	"  -P, --privilege  Enable privileged mode\n" +
	"  -V, --version    Show version\n\n" +
	"Help Options:\n" +
	"  -h, --help       Show this help message\n\n"

const versionText = "pingu: v-rev8ff82f4\n"
const countFlag = "-c, --count"

// options describes the public command line. Help is handled as soon as it is
// encountered, while version is handled only after the full command is parsed.
type options struct {
	count     int
	privilege bool
	version   bool
	help      bool
	hosts     []string
}

func flagKind(s string) int {
	if len(s) < 2 || s[0] != '-' {
		return 0
	}
	if s[1] != '-' {
		return 1
	}
	if len(s) > 2 && s[2] != '-' {
		return 2
	}
	return 0
}

func unknownFlag(name string) error {
	return fmt.Errorf("unknown flag `%s'", name)
}

func boolArgument(name string) error {
	return fmt.Errorf("bool flag `%s' cannot have an argument", name)
}

func missingCount() error {
	return fmt.Errorf("expected argument for flag `%s'", countFlag)
}

func parseCLI(args []string) (options, error) {
	o := options{count: 20}
	endOptions := false
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if endOptions {
			o.hosts = append(o.hosts, arg)
			continue
		}
		if arg == "--" {
			endOptions = true
			continue
		}

		setCount := func(value string) error {
			n, err := strconv.ParseInt(value, 10, strconv.IntSize)
			if err != nil {
				return fmt.Errorf("invalid argument for flag `%s' (expected int): %s", countFlag, err)
			}
			o.count = int(n)
			return nil
		}
		nextCount := func() error {
			if i+1 == len(args) {
				return missingCount()
			}
			value := args[i+1]
			if value == "--" {
				return fmt.Errorf("expected argument for flag `%s', but got double dash `--'", countFlag)
			}
			negativeNumber := len(value) > 1 && value[0] == '-' && value[1] >= '0' && value[1] <= '9'
			if flagKind(value) != 0 && !negativeNumber {
				return fmt.Errorf("expected argument for flag `%s', but got option `%s'", countFlag, value)
			}
			i++
			return setCount(value)
		}

		switch flagKind(arg) {
		case 0:
			o.hosts = append(o.hosts, arg)
		case 2:
			name, value, hasValue := strings.Cut(arg[2:], "=")
			switch name {
			case "count":
				var err error
				if hasValue {
					err = setCount(value)
				} else {
					err = nextCount()
				}
				if err != nil {
					return o, err
				}
			case "privilege", "version", "help":
				fullName := map[string]string{
					"privilege": "-P, --privilege", "version": "-V, --version", "help": "-h, --help",
				}[name]
				if hasValue {
					return o, boolArgument(fullName)
				}
				switch name {
				case "privilege":
					o.privilege = true
				case "version":
					o.version = true
				case "help":
					o.help = true
					return o, nil
				}
			default:
				return o, unknownFlag(name)
			}
		case 1:
			letters := arg[1:]
			first := true
			for len(letters) != 0 {
				letter, width := utf8.DecodeRuneInString(letters)
				letters = letters[width:]
				switch letter {
				case 'c':
					var err error
					if first && len(letters) > 0 {
						err = setCount(strings.TrimPrefix(letters, "="))
					} else if len(letters) > 0 {
						err = missingCount()
					} else {
						err = nextCount()
					}
					if err != nil {
						return o, err
					}
					letters = ""
				case 'P', 'V', 'h':
					if first && strings.HasPrefix(letters, "=") {
						name := map[rune]string{'P': "-P, --privilege", 'V': "-V, --version", 'h': "-h, --help"}[letter]
						return o, boolArgument(name)
					}
					switch letter {
					case 'P':
						o.privilege = true
					case 'V':
						o.version = true
					case 'h':
						o.help = true
						return o, nil
					}
				default:
					return o, unknownFlag(string(letter))
				}
				first = false
			}
		}
	}
	return o, nil
}
EOF
