cat > display.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"math"
	"os"
	"syscall"
	"time"
	"unsafe"
)

type display struct {
	out   io.Writer
	err   io.Writer
	color bool
}

func terminalColor() bool {
	if os.Getenv("NO_COLOR") != "" || os.Getenv("TERM") == "dumb" {
		return false
	}
	var state syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), syscall.TCGETS, uintptr(unsafe.Pointer(&state)))
	return err == 0
}

func (d display) inline(code int, value interface{}) string {
	s := fmt.Sprint(value)
	if !d.color {
		return s
	}
	return fmt.Sprintf("\x1b[%d;1m%s\x1b[0;22m", code, s)
}

func (d display) whole(code int, s string) {
	if d.color {
		fmt.Fprintf(d.out, "\x1b[%d;1m%s\x1b[0m", code, s)
	} else {
		fmt.Fprint(d.out, s)
	}
}

func (d display) errorf(format string, args ...interface{}) {
	fmt.Fprintf(d.err, "[ %s ] %s\n", d.inline(31, "ERROR"), fmt.Sprintf(format, args...))
}

func (d display) start(host, addr string) {
	d.whole(97, fmt.Sprintf("PING %s (%s) type `Ctrl-C` to abort\n", host, addr))
}

func (d display) reply(seq, size int, addr string, ttl int, elapsed time.Duration) {
	fmt.Fprintf(d.out, "%sseq=%s %sbytes from %s: ttl=%s time=%s\n", d.art(seq),
		d.inline(93, seq), d.inline(94, size), d.inline(37, addr), d.inline(96, ttl), d.inline(95, elapsed))
}

type statistics struct {
	sent, received  int
	min, avg, max  time.Duration
	variance      float64
}

func (s *statistics) add(elapsed time.Duration) {
	s.received++
	if s.received == 1 || elapsed < s.min {
		s.min = elapsed
	}
	if elapsed > s.max {
		s.max = elapsed
	}
	delta := elapsed - s.avg
	s.avg += delta / time.Duration(s.received)
	s.variance += float64(delta) * float64(elapsed-s.avg)
}

func (s statistics) stddev() time.Duration {
	if s.received == 0 {
		return 0
	}
	return time.Duration(math.Sqrt(s.variance / float64(s.received)))
}

func (d display) finish(host string, s statistics) {
	d.whole(37, fmt.Sprintf("\n───────── %s ping statistics ─────────\n", host))
	loss := (float64(s.sent-s.received) / float64(s.sent)) * 100
	fmt.Fprintf(d.out, "%s: %s transmitted => %s received (%s loss)\n",
		d.inline(97, "PACKET STATISTICS"), d.inline(94, s.sent), d.inline(92, s.received),
		d.inline(91, fmt.Sprintf("%v%%", loss)))
	fmt.Fprintf(d.out, "%s: min=%s avg=%s max=%s stddev=%s\n",
		d.inline(97, "ROUND TRIP"), d.inline(94, s.min), d.inline(96, s.avg), d.inline(92, s.max), d.inline(35, s.stddev()))
}
EOF
cat > main.go <<'EOF'
package main

import (
	"fmt"
	"net"
	"os"
)

func run(args []string, d display) int {
	o, err := parseCLI(args)
	if err != nil {
		fmt.Fprintln(d.err, err)
		d.errorf("parse error: %s", err)
		return 1
	}
	if o.help {
		fmt.Fprint(d.out, helpText)
		return 0
	}
	if o.version {
		fmt.Fprint(d.out, versionText)
		return 0
	}
	if len(o.hosts) == 0 {
		d.errorf("must requires an argument")
		return 1
	}
	if len(o.hosts) != 1 {
		d.errorf("too many arguments")
		return 1
	}
	host := o.hosts[0]
	if host == "" {
		d.errorf("an error occurred while initializing pinger: failed to init pinger addr cannot be empty")
		return 0
	}
	addr, err := net.ResolveIPAddr("ip", host)
	if err != nil {
		d.errorf("an error occurred while initializing pinger: failed to init pinger %s", err)
		return 0
	}
	d.start(host, addr.String())
	if err := pingHost(host, addr, o, d); err != nil {
		d.errorf("an error occurred when running ping: %s", err)
		return 2
	}
	return 0
}

func main() {
	os.Exit(run(os.Args[1:], display{out: os.Stdout, err: os.Stderr, color: terminalColor()}))
}
EOF
