// echoSocket provides the same packet interface for a datagram ICMP socket
// (available to unprivileged users on Linux) and a raw IP socket.
type echoSocket struct {
	udp  *net.UDPConn
	raw  *net.IPConn
	v4   bool
}

func openEchoSocket(v4, privileged bool) (*echoSocket, error) {
	s := &echoSocket{v4: v4}
	network := "ip6:ipv6-icmp"
	family, protocol := syscall.AF_INET6, syscall.IPPROTO_ICMPV6
	if v4 {
		network = "ip4:icmp"
		family, protocol = syscall.AF_INET, syscall.IPPROTO_ICMP
	}
	if privileged {
		p, err := net.ListenIP(network, &net.IPAddr{})
		if err != nil {
			return nil, err
		}
		s.raw = p
	} else {
		// These are ICMP ping sockets, not ordinary UDP network traffic. Using
		// a UDPConn for the descriptor gives us deadline-aware packet I/O.
		fd, err := syscall.Socket(family, syscall.SOCK_DGRAM|syscall.SOCK_CLOEXEC|syscall.SOCK_NONBLOCK, protocol)
		if err != nil {
			return nil, fmt.Errorf("socket: %s", err)
		}
		var bindAddr syscall.Sockaddr = &syscall.SockaddrInet6{}
		if v4 {
			bindAddr = &syscall.SockaddrInet4{}
		}
		if err := syscall.Bind(fd, bindAddr); err != nil {
			syscall.Close(fd)
			return nil, fmt.Errorf("bind: %s", err)
		}
		file := os.NewFile(uintptr(fd), "icmp")
		conn, err := net.FilePacketConn(file)
		file.Close()
		if err != nil {
			return nil, err
		}
		udp, ok := conn.(*net.UDPConn)
		if !ok {
			conn.Close()
			return nil, fmt.Errorf("invalid ICMP socket")
		}
		s.udp = udp
	}
	var raw syscall.RawConn
	var err error
	if s.udp != nil {
		raw, err = s.udp.SyscallConn()
	} else {
		raw, err = s.raw.SyscallConn()
	}
	if err != nil {
		s.close()
		return nil, err
	}
	// The TTL/hop limit returned with each reply is ancillary socket data.
	raw.Control(func(fd uintptr) {
		if v4 {
			syscall.SetsockoptInt(int(fd), syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1)
		} else {
			syscall.SetsockoptInt(int(fd), syscall.IPPROTO_IPV6, syscall.IPV6_RECVHOPLIMIT, 1)
		}
	})
	return s, nil
}

func (s *echoSocket) close() {
	if s.udp != nil {
		s.udp.Close()
	} else {
		s.raw.Close()
	}
}

func (s *echoSocket) write(b []byte, addr *net.IPAddr) error {
	var err error
	if s.udp != nil {
		_, err = s.udp.WriteToUDP(b, &net.UDPAddr{IP: addr.IP, Zone: addr.Zone})
	} else {
		_, err = s.raw.WriteToIP(b, addr)
	}
	return err
}

func (s *echoSocket) read(b, control []byte) (int, int, error) {
	var n, controlLen int
	var err error
	if s.udp != nil {
		n, controlLen, _, _, err = s.udp.ReadMsgUDP(b, control)
	} else {
		n, controlLen, _, _, err = s.raw.ReadMsgIP(b, control)
	}
	if err != nil {
		return 0, 0, err
	}
	ttl := 0
	messages, _ := syscall.ParseSocketControlMessage(control[:controlLen])
	for _, message := range messages {
		if (message.Header.Level == syscall.IPPROTO_IP && message.Header.Type == syscall.IP_TTL) ||
			(message.Header.Level == syscall.IPPROTO_IPV6 && message.Header.Type == syscall.IPV6_HOPLIMIT) {
			if len(message.Data) >= 4 {
				ttl = int(binary.NativeEndian.Uint32(message.Data))
			}
		}
	}
	return n, ttl, nil
}

func checksum(packet []byte) uint16 {
	var sum uint32
	for len(packet) >= 2 {
		sum += uint32(binary.BigEndian.Uint16(packet))
		packet = packet[2:]
	}
	if len(packet) != 0 {
		sum += uint32(packet[0]) << 8
	}
	for sum>>16 != 0 {
		sum = sum&0xffff + sum>>16
	}
	return ^uint16(sum)
}

type echoReply struct {
	seq     int
	size    int
	ttl     int
	elapsed time.Duration
	err     error
}

func pingHost(host string, addr *net.IPAddr, opts options, d display) error {
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt)
	defer signal.Stop(stop)

	v4 := addr.IP.To4() != nil
	conn, err := openEchoSocket(v4, opts.privilege)
	if err != nil {
		return err
	}
	defer conn.close()
	stats := statistics{}
	defer func() { d.finish(host, stats) }()

	var marker [16]byte
	rand.Read(marker[:])
	id := uint16(os.Getpid())
	if conn.udp != nil {
		id = uint16(conn.udp.LocalAddr().(*net.UDPAddr).Port)
	}

	done := make(chan struct{})
	defer close(done)
	replies := make(chan echoReply, 32)
	go func() {
		buffer := make([]byte, 65536)
		control := make([]byte, 128)
		for {
			n, ttl, err := conn.read(buffer, control)
			if err != nil {
				select {
				case replies <- echoReply{err: err}:
				case <-done:
				}
				return
			}
			arrival := time.Now()
			packet := buffer[:n]
			// ReadMsgIP normally removes IPv4's outer IP header; also handle
			// systems where it is delivered with the raw message.
			if v4 && len(packet) > 0 && packet[0]>>4 == 4 {
				headerLen := int(packet[0]&15) * 4
				if headerLen > len(packet) {
					continue
				}
				packet = packet[headerLen:]
			}
			kind := byte(129)
			if v4 {
				kind = 0
			}
			if len(packet) < 32 || packet[0] != kind || packet[1] != 0 ||
				binary.BigEndian.Uint16(packet[4:6]) != id || !bytes.Equal(packet[16:32], marker[:]) {
				continue
			}
			stamp := int64(binary.BigEndian.Uint64(packet[8:16]))
			reply := echoReply{
				seq: int(binary.BigEndian.Uint16(packet[6:8])), size: len(packet), ttl: ttl,
				elapsed: time.Duration(arrival.UnixNano() - stamp),
			}
			select {
			case replies <- reply:
			case <-done:
				return
			}
		}
	}()

	seq := 0
	seen := make(map[int]bool)
	send := func() error {
		packet := make([]byte, 32)
		packet[0] = 128
		if v4 {
			packet[0] = 8
		}
		binary.BigEndian.PutUint16(packet[4:6], id)
		binary.BigEndian.PutUint16(packet[6:8], uint16(seq))
		binary.BigEndian.PutUint64(packet[8:16], uint64(time.Now().UnixNano()))
		copy(packet[16:], marker[:])
		if v4 {
			binary.BigEndian.PutUint16(packet[2:4], checksum(packet))
		}
		if err := conn.write(packet, addr); err != nil {
			return err
		}
		delete(seen, seq)
		seq = (seq + 1) & 0xffff
		stats.sent++
		return nil
	}

	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	if err := send(); err != nil {
		return err
	}
	for {
		select {
		case <-stop:
			return nil
		case reply := <-replies:
			if reply.err != nil {
				return reply.err
			}
			if seen[reply.seq] {
				continue
			}
			seen[reply.seq] = true
			stats.add(reply.elapsed)
			d.reply(reply.seq, reply.size, addr.String(), reply.ttl, reply.elapsed)
			if opts.count > 0 && stats.received >= opts.count {
				return nil
			}
		case <-ticker.C:
			if opts.count <= 0 || stats.sent < opts.count {
				if err := send(); err != nil {
					return err
				}
			}
		}
	}
}
