			if len(message.Data) >= 4 {
				ttl = int(binary.NativeEndian.Uint32(message.Data))
			}
		}
	}
	return n, ttl, nil
}

func checksum(packet []byte) uint16 {
	var sum uint32
	for len(packet) >= 2 {
		sum += uint32(binary.BigEndian.Uint16(packet))
		packet = packet[2:]
	}
	if len(packet) != 0 {
		sum += uint32(packet[0]) << 8
	}
	for sum>>16 != 0 {
		sum = sum&0xffff + sum>>16
	}
	return ^uint16(sum)
}

type echoReply struct {
	seq     int
	size    int
	ttl     int
	elapsed time.Duration
	err     error
}

func pingHost(host string, addr *net.IPAddr, opts options, d display) error {
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt)
	defer signal.Stop(stop)

	v4 := addr.IP.To4() != nil
	conn, err := openEchoSocket(v4, opts.privilege)
	if err != nil {
		return err
	}
	defer conn.close()
	stats := statistics{}
	defer func() { d.finish(host, stats) }()

	var marker [16]byte
	rand.Read(marker[:])
	id := uint16(os.Getpid())
	if conn.udp != nil {
		id = uint16(conn.udp.LocalAddr().(*net.UDPAddr).Port)
	}

	done := make(chan struct{})
	defer close(done)
	replies := make(chan echoReply, 32)
	go func() {
		buffer := make([]byte, 65536)
		control := make([]byte, 128)
		for {
			n, ttl, err := conn.read(buffer, control)
			if err != nil {
				select {
				case replies <- echoReply{err: err}:
				case <-done:
				}
				return
			}
			arrival := time.Now()
			packet := buffer[:n]
			// ReadMsgIP normally removes IPv4's outer IP header; also handle
			// systems where it is delivered with the raw message.
			if v4 && len(packet) > 0 && packet[0]>>4 == 4 {
				headerLen := int(packet[0]&15) * 4
				if headerLen > len(packet) {
					continue
				}
				packet = packet[headerLen:]
			}
			kind := byte(129)
			if v4 {
				kind = 0
			}
			if len(packet) < 32 || packet[0] != kind || packet[1] != 0 ||
				binary.BigEndian.Uint16(packet[4:6]) != id || !bytes.Equal(packet[16:32], marker[:]) {
				continue
			}
			stamp := int64(binary.BigEndian.Uint64(packet[8:16]))
			reply := echoReply{
				seq: int(binary.BigEndian.Uint16(packet[6:8])), size: len(packet), ttl: ttl,
				elapsed: time.Duration(arrival.UnixNano() - stamp),
			}
			select {
			case replies <- reply:
			case <-done:
				return
			}
		}
	}()

	seq := 0
	seen := make(map[int]bool)
	send := func() error {
		packet := make([]byte, 32)
		packet[0] = 128
		if v4 {
			packet[0] = 8
		}
		binary.BigEndian.PutUint16(packet[4:6], id)
		binary.BigEndian.PutUint16(packet[6:8], uint16(seq))
		binary.BigEndian.PutUint64(packet[8:16], uint64(time.Now().UnixNano()))
		copy(packet[16:], marker[:])
		if v4 {
			binary.BigEndian.PutUint16(packet[2:4], checksum(packet))
		}
		if err := conn.write(packet, addr); err != nil {
			return err
		}
		delete(seen, seq)
		seq = (seq + 1) & 0xffff
		stats.sent++
		return nil
	}

	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	if err := send(); err != nil {
		return err
	}
	for {
		select {
		case <-stop:
			return nil
		case reply := <-replies:
			if reply.err != nil {
				return reply.err
			}
			if seen[reply.seq] {
				continue
			}
			seen[reply.seq] = true
			stats.add(reply.elapsed)
			d.reply(reply.seq, reply.size, addr.String(), reply.ttl, reply.elapsed)
			if opts.count > 0 && stats.received >= opts.count {
				return nil
			}
		case <-ticker.C:
			if opts.count <= 0 || stats.sent < opts.count {
				if err := send(); err != nil {
					return err
				}
			}
		}
	}
}
