package main

import (
	"fmt"
	"strings"
)

// Completion mode is a separate, non-executing interface. All but the last
// argument establish context; the final argument is an unfinished shell word.
func complete(args []string, verbose bool) string {
	if len(args) == 0 {
		return ""
	}
	pending, endOptions := false, false
	for _, arg := range args[:len(args)-1] {
		if pending {
			pending = false
			continue
		}
		if endOptions {
			continue
		}
		if arg == "--" {
			endOptions = true
			continue
		}
		if arg == "--count" {
			pending = true
			continue
		}
		if flagKind(arg) != 1 {
			continue
		}
		letters := arg[1:]
		for i, letter := range letters {
			switch letter {
			case 'c':
				pending = i == len(letters)-1
			case 'P', 'V', 'h':
				continue
			}
			break
		}
	}
	if pending {
		return ""
	}
	word := args[len(args)-1]
	if strings.Contains(word, "=") {
		return ""
	}
	if flagKind(word) == 1 && word != "-" {
		if word[1] == 'c' {
			return ""
		}
		return word + "\n"
	}
	if !strings.HasPrefix(word, "-") {
		return ""
	}
	names := []string{"--count", "--help", "--privilege", "--version"}
	descriptions := []string{"Stop after <count> replies", "Show this help message", "Enable privileged mode", "Show version"}
	var matches []int
	for i, name := range names {
		if strings.HasPrefix(name, word) {
			matches = append(matches, i)
		}
	}
	var result strings.Builder
	for _, i := range matches {
		if verbose && len(matches) > 1 {
			fmt.Fprintf(&result, "%-11s  # %s\n", names[i], descriptions[i])
		} else {
			fmt.Fprintln(&result, names[i])
		}
	}
	return result.String()
}
EOF
